  }
  else
  {
    if ((event != EVENT_RESOLVE_ACTIVATION) && (event != EVENT_CLEANUP))
    {
      return 0;
    }
    default_target_definition(player, card, &td1, 0x100);
  }
  td1.zone = 0x1000;
  if (event == EVENT_RESOLVE_ACTIVATION)
