    if (spell_fizzled == 1)
      remove_state(player, card, 0x10);
    tapped_for_mana_color = -1;
    return 0;
  }
  if (event == EVENT_RESOLVE_ACTIVATION)
  {
    if (instance->info_slot == CHOICE_EXILE)
