      int selected = validate_target_from_grave_source(player, card, player, 0);
      if (selected >= 0)
      {
        int leg = 0, idx = 0;
        exiledby_remember(player, instance->parent_card, player, get_grave(player)[selected], &leg,
                          &idx);
        rfg_card_from_grave(player, selected);
