    mode_life_or_scan = dialog_impl(player, card, event, "\001\002", "\001\017", "Gain 2 life", 1,
                                    ((life[player] < 6) - 1 & 0xfffffff1) + 0x14, 1,
                                    "Give a +1/+1 counters to your crits", 1,
