      {
        spell_fizzled = 1;
        return 0;
      }
      if (choice != CHOICE_MANA)
      {
        if (choice != CHOICE_DECK)
        {
          return 0;
        }
        return generic_activated_ability(player, card, EVENT_ACTIVATE, 0, 5, 0, 0, 0, 0, 0, 0, NULL,
