                (result = has_subtype_by_id(player, (unsigned int)cards_data[*exile_cursor].id,
                                            SUBTYPE_AURA),
                 result != 0))
            {
              remove_card_from_rfg(turn_or_csvid, (unsigned int)cards_data[*exile_cursor].id);
              raw_put_iid_on_top_of_deck(turn_or_csvid, *exile_cursor);
              *exile_cursor = -1;
