                                                 commanders[owner_or_opponent].edh_card);
                    *(uint8_t *)((int)&instance->targets[3].player + 1) = 4;
                    commander_enters_the_battlefield(owner_or_opponent,
                                                     commanders[owner_or_opponent].edh_card, player,
                                                     value, 2);
                    put_into_play(player, value);
