          } while (exile_end != exile_cursor);
        }
        pass = pass + 1;
      } while (pass != 2);
      // Native cleanup starts at the returned count, inclusive.
      value = count_rfg(turn_or_csvid);
      if (-1 < value)
      {
        do
        {
