  vanguard_card(player, card, event, 7, 0x28, 6);

  instance = get_card_instance(player, card);

  etb_ability(player, card, event, RESOLVE_TRIGGER_MANDATORY);
  if (event == EVENT_ETB)
  {
    int options[available_slots];

    for (i = 0; i < available_slots; ++i)
      options[i] = 0;
